// n8n Code node - "Run Once for All Items" mode

function parseDateOnly(dateTimeStr) {
  if (!dateTimeStr) return null;
  return dateTimeStr.split(' ')[0]; // "2025-04-18 13:37:32" -> "2025-04-18"
}

function parseNumber(value) {
  if (typeof value !== 'string') return NaN;

  const hasComma = value.includes(',');
  const hasDot = value.includes('.');

  let normalized = value;

  if (hasComma && hasDot) {
    // assume dot = thousand separator, comma = decimal
    normalized = value.replace(/\./g, '').replace(',', '.');
  } else if (hasComma) {
    // comma as decimal
    normalized = value.replace(',', '.');
  }

  return parseFloat(normalized);
}

function mapType(amountStr) {
  const amount = parseFloat(amountStr);
  if (isNaN(amount)) return 'withdrawal';
  return amount < 0 ? 'withdrawal' : 'deposit';
}

// cyrb53 - fast, deterministic, dependency-free 53-bit hash
// (no crypto module needed, works in n8n's sandboxed Code node)
function cyrb53(str, seed = 0) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 4294967296 * (h2 >>> 0) + (h1 >>> 0);
}

function generateExternalId(raw) {
  const seed = [
    raw['Type'],
    raw['Started Date'],
    raw['Completed Date'],
    raw['Description'],
    raw['Amount'],
    raw['Fee'],
    raw['Currency'],
    raw['Balance'],
  ].join('|');
  const num = cyrb53(seed);
  return num.toString().padStart(10, '0').slice(-10);
}

function buildAccountName(product) {
  return `revolut-${(product || 'account').toString().toLowerCase()}`;
}

const results = [];

for (const raw of $json.data) {

  const type = mapType(raw['Amount']);
  const amount = Math.abs(parseNumber(raw['Amount'])).toFixed(2);
  const date = parseDateOnly(raw['Started Date']);
  const bookDate = parseDateOnly(raw['Completed Date']);
  const account = buildAccountName(raw['Product']);
  const externalId = generateExternalId(raw);

  const counterpartyName = raw['Description'] || 'Revolut';
  const fee = parseNumber(raw['Fee']);

  const notesParts = [
    raw['Type'] ? `Type: ${raw['Type']}` : null,
    raw['State'] && raw['State'] !== 'COMPLETED' ? `State: ${raw['State']}` : null,
    fee && fee !== 0 ? `Fee: ${fee.toFixed(2)} ${raw['Currency']}` : null,
    raw['Balance'] ? `Balance after: ${raw['Balance']} ${raw['Currency']}` : null,
  ].filter(Boolean);

  const normalized = {
    id: `${account}-${externalId}`,
    account,
    type,
    date,
    amount,
    currency_code: raw['Currency'] || null,
    description: raw['Description'] || '',
    category_name: null,

    ...(type === 'withdrawal'
      ? { destination_name: counterpartyName, destination_iban: null, destination_bic: null }
      : { source_name: counterpartyName, source_iban: null, source_bic: null }),

    external_id: externalId,
    internal_reference: null,

    payment_date: date,
    book_date: bookDate,

    tags: raw['Type'] ? [raw['Type']] : [],

    notes: notesParts.length ? notesParts.join(' | ') : null,

    raw,
  };

  results.push(normalized);
}

return {json:{...$json, data: results}};

